// === Tab: mySketch ===
// A RobRed Sketch

// Curated for the weekly creative code challenge on the theme "Radioactivity" hosted by Raphaël de Courville. #WCCChallenge

/*
	Cherenkov Blue: Imagine moving faster than the light.
	Well, that may never be possible, but who said we have to let light travel at its full speed?
	When light travels through a dense medium like water, it slows down just enough for a high-energy particle to take the lead.
	Much like the sonic boom shockwave observed in the air when a jet plane surpasses the speed of sound,
	a radioactive particle traveling faster than light creates a shockwave of electromagnetic radiation.
	That vivid, hauntingly beautiful glow, known as Cherenkov radiation, is the literal result of this "luminal boom."

 Sketch Description:

	The Alpha Particle Core: A dense orb of high-energy particles governed by harmonic Lissajous curves.
	These particles oscillate within a tightly packed circular space,
	creating a luminescent core that pulses with varying radioactive-blue intensity.

	The Beta Particle Background: An erratic field of ionizing particles simulating spontaneous Geiger discharges.
	These rapidly accelerating and decelerating particles leave behind transient,
	glowing trails that mimic the ionization paths observed in a cloud chamber.
*/

const betaQuant = 200;
const alphaQuant = 300;
const alphaCoreRadius = 25;

let betaParticles = [];
let alphaParticles = [];

function setup() {
	createCanvas(windowWidth, windowHeight);
	colorMode(HSB, 360, 100, 100, 300);
	rectMode(CENTER);
	noStroke();

	for (let b = 0; b < betaQuant; b++) {
		const betaPos = createVector(random(width), random(height));
		const betaSize = random(0.5, 2.5);

		betaParticles.push(new BetaParticle(betaPos, betaSize));
	}

	for (let a = 0; a < alphaQuant; a++) {
		const angle = random(TWO_PI);
		const r = random(alphaCoreRadius);
		const fx = sq(r) / 10000;
		const ft = exp(-fx);
		const offsetPos = createVector(cos(angle) * r, sin(angle) * r);

		alphaParticles.push(new AlphaParticle(offsetPos, ft));
	}
}

function draw() {
	blendMode(BLEND);

	background(5, 5, 5, 25);

	blendMode(ADD);

	for (let pBeta of betaParticles) {
		pBeta.update();
		pBeta.display();
	}

	for (const pAlpha of alphaParticles) {
		pAlpha.update();
		pAlpha.display();
	}
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
}

// === Tab: tab2 ===
class BetaParticle {
	constructor(pos, size) {
		this.pos = pos;
		this.size = size;

		this.angle = Math.random() * TWO_PI;
		this.currentSpeed = 0;

		this.hue = 190 + Math.random() * 20;
		this.sat = 20 + Math.random() * 60;
		this.brightness = 60 + Math.random() * 20;
	}

	update() {
		if (Math.random() < 0.05) {
			this.angle = Math.random() * TWO_PI;
			this.currentSpeed = 30 + Math.random() * 20;
		} else {
			this.currentSpeed *= 0.93;
			this.angle += (Math.random() - 0.5) * 0.1;
		}

		this.pos.x += cos(this.angle) * this.currentSpeed;
		this.pos.y += sin(this.angle) * this.currentSpeed;

		this.checkEdges();
	}

	checkEdges() {
		if (this.pos.x < 0) this.pos.x = width;
		if (this.pos.x > width) this.pos.x = 0;
		if (this.pos.y < 0) this.pos.y = height;
		if (this.pos.y > height) this.pos.y = 0;
	}

	display() {
		const flashAlpha = map(this.currentSpeed, 0, 50, 250, 50, true);

		fill(this.hue, this.sat, this.brightness, flashAlpha);
		square(this.pos.x, this.pos.y, this.size);
	}
}

// === Tab: tab3 ===
class AlphaParticle {
	constructor(offsetPos, ft) {
		this.baseOffset = offsetPos.copy();
		this.pos = createVector(0, 0);
		this.size = ft * 4;

		this.hue = 220 + (Math.random() - 0.5) * 20;
		this.sat = 80 + Math.random() * 20;
		this.brightness = 70 + Math.random() * 30;
		this.alpha = 0;

		this.amp = 6;
		this.offset = Math.random() * 10000;

		this.m = 10;
		this.n = 10;
		this.p = 10;
		this.q = 10;

		this.a = 15;
		this.b = 7;
		this.c = 7;
		this.d = 15;

		const maxDx = (Math.abs(this.m) + Math.abs(this.p)) * this.amp;
		const maxDy = (Math.abs(this.n) + Math.abs(this.q)) * this.amp;

		this.maxEnergy = (maxDx + maxDy) / 2;
	}

	update() {
		const t = millis() * 0.0001 + this.offset;

		const dx1 = (cos(t * this.a) * this.m + sin(t * this.c) * this.p) * this.amp;
		const dy1 = (cos(t * this.b) * this.n + sin(t * this.d) * this.q) * this.amp;

		const dx2 = (sin(t * this.a) * this.m + sin(t * this.c) * this.p) * this.amp;
		const dy2 = (cos(t * this.b) * this.n + cos(t * this.d) * this.q) * this.amp;

		const dx3 = (sin(t * this.a) * this.m + cos(t * this.c) * this.p) * this.amp;
		const dy3 = (sin(t * this.b) * this.n + cos(t * this.d) * this.q) * this.amp;

		this.pos.x1 = width / 2 + this.baseOffset.x + dx1;
		this.pos.y1 = height / 2 + this.baseOffset.y - dy1;

		this.pos.x2 = width / 2 + this.baseOffset.x + dx2;
		this.pos.y2 = height / 2 + this.baseOffset.y - dy2;

		this.pos.x3 = width / 2 + this.baseOffset.x + dx3;
		this.pos.y3 = height / 2 + this.baseOffset.y - dy3;

		const energy = (Math.abs(dx2) + Math.abs(dy2)) / 2;
		this.alpha = map(energy, 0, this.maxEnergy, 0, 250, true);
	}

	display() {
		fill(this.hue, this.sat, this.brightness, this.alpha);
		square(this.pos.x1, this.pos.y1, this.size);

		fill(this.hue, this.sat, this.brightness, this.alpha);
		square(this.pos.x2, this.pos.y2, this.size);

		fill(this.hue, this.sat, this.brightness, this.alpha);
		square(this.pos.x3, this.pos.y3, this.size);
	}
}

